//! NEC Studio's engine commands for the browser.
//!
//! `engine.rs` is NEC Studio's engine bridge, generated by `scripts/sync_vendor.py`. This file
//! stands in for the Tauri shell in nec-rs's `app/src-tauri/src/main.rs`: one [`call`] export
//! takes the same command names and the same argument objects the desktop frontend passes to
//! Tauri's `invoke` (as JSON text), and returns the same results (as JSON text). Long jobs report
//! progress through the `on_event` callback where the desktop app emitted Tauri events.
//!
//! What differs from the desktop shell, and why:
//! - No file system: projects are opened from and saved to text (`open_project`,
//!   `project_text`); the page handles uploads and downloads.
//! - One in-memory Green's-function store per worker instead of one per deck folder.
//! - Cancellation is done by the page terminating the worker running the job, because a
//!   single-threaded computation cannot see a flag set from outside while it runs. The engine's
//!   cancel flags are passed but never set.

mod engine;

use nec_engine::sweep::{self, linspace};
use nec_engine::{checks, matching};
use nec_engine::{EvalOptions, Frame, Metrics, Model, ModelOptions, NgfStore, OptimizeSpec, Project, SliceRequest};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};
use std::cell::RefCell;
use std::path::Path;
use std::sync::atomic::AtomicBool;
use wasm_bindgen::prelude::*;
use web_time::{Duration, Instant};

thread_local! {
    /// The Green's-function store: a `WG` deck's result is still there for the `GF` deck
    /// solved after it in the same worker. Nothing is written to disk.
    static STORE: RefCell<NgfStore> = RefCell::new(NgfStore::default());
    /// Where progress events go while a [`call`] runs. A thread local rather than a captured
    /// value because the engine's callbacks must be `Sync` and a JS function is not; the
    /// browser build is single-threaded, so every callback runs on this thread.
    static ON_EVENT: RefCell<Option<js_sys::Function>> = const { RefCell::new(None) };
}

/// Run one NEC Studio command.
///
/// `cmd` is the Tauri command name and `args` the JSON of the object the desktop frontend
/// passes to `invoke` for it. The result is the command's return value as JSON. `on_event`,
/// when given, receives `(event_name, payload_json)` for each sweep point, optimizer
/// improvement or convergence step, the events the desktop app emitted.
#[wasm_bindgen]
pub fn call(cmd: &str, args: &str, on_event: Option<js_sys::Function>) -> Result<String, String> {
    ON_EVENT.with(|cb| *cb.borrow_mut() = on_event);
    let result = dispatch(cmd, args);
    ON_EVENT.with(|cb| *cb.borrow_mut() = None);
    result
}

fn emit<T: Serialize>(event: &str, payload: &T) {
    let Ok(json) = serde_json::to_string(payload) else { return };
    ON_EVENT.with(|cb| {
        if let Some(f) = cb.borrow().as_ref() {
            let _ = f.call2(&JsValue::NULL, &JsValue::from_str(event), &JsValue::from_str(&json));
        }
    });
}

fn parse<T: DeserializeOwned>(json: &str) -> Result<T, String> {
    serde_json::from_str(json).map_err(|e| format!("bad arguments: {e}"))
}

fn out<T: Serialize>(value: &T) -> Result<String, String> {
    serde_json::to_string(value).map_err(|e| e.to_string())
}

fn store() -> NgfStore {
    STORE.with(|s| s.borrow().clone())
}

// ---- argument objects, as the frontend's api.ts sends them ----------------------------

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeckArgs {
    text: String,
    #[serde(default)]
    model: Option<ModelOptions>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AtArgs {
    text: String,
    mhz: Option<f64>,
    #[serde(default)]
    model: Option<ModelOptions>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SolveArgs {
    text: String,
    mhz: Option<f64>,
    z0: f64,
    #[serde(default)]
    model: Option<ModelOptions>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct NearArgs {
    text: String,
    mhz: Option<f64>,
    request: SliceRequest,
    #[serde(default)]
    model: Option<ModelOptions>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct TextArgs {
    text: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct VariablesArgs {
    text: String,
    values: Vec<(String, f64)>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CardArgs {
    text: String,
    line: usize,
    mnemonic: String,
    fields: Vec<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct LineArgs {
    text: String,
    line: usize,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DesignArgs {
    z: [f64; 2],
    z0: f64,
    mhz: f64,
    request: MatchRequest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ApplyArgs {
    text: String,
    tag: i32,
    segment: usize,
    network: matching::Network,
    mhz: f64,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoveArgs {
    text: String,
    dummy_tag: i32,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct OpenArgs {
    /// The file name: `.toml` opens as a project, anything else as a NEC deck.
    name: String,
    text: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SaveArgs {
    /// The file name: `.toml` saves the whole project, anything else only the deck.
    name: String,
    project: Project,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SweepArgs {
    job: u64,
    text: String,
    start: f64,
    stop: f64,
    steps: usize,
    options: EvalOptions,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ParameterArgs {
    job: u64,
    text: String,
    name: String,
    start: f64,
    stop: f64,
    steps: usize,
    mhz: f64,
    options: EvalOptions,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct OptimizeArgs {
    job: u64,
    text: String,
    spec: OptimizeSpec,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AverageGainArgs {
    text: String,
    mhz: Option<f64>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ConvergenceArgs {
    text: String,
    mhz: f64,
    steps: usize,
    growth: f64,
    options: EvalOptions,
}

// ---- result types, as in the desktop shell ---------------------------------------------

/// The deck's geometry cards, for the editor's table, and the line a new one goes before.
#[derive(Serialize)]
struct GeometryCards {
    cards: Vec<nec_cards::edit::CardLine>,
    insert_at: Option<usize>,
}

/// What a matching design asks for.
#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
enum MatchRequest {
    L { q_l: f64, q_c: f64 },
    Pi { q_net: f64, q_l: f64, q_c: f64 },
    Tee { q_net: f64, q_l: f64, q_c: f64 },
    Stub { line: matching::Line, stub_line: matching::Line, short: bool, series: bool },
    Section { line: matching::Line, section: matching::Line },
}

/// A designed network and how it performs on the antenna it was designed for.
#[derive(Serialize)]
struct MatchDesign {
    network: matching::Network,
    z_in: [f64; 2],
    swr: f64,
    loss: f64,
}

/// A matching network already in the deck.
#[derive(Serialize)]
struct MatchInDeck {
    dummy_tag: i32,
    feed_tag: String,
    feed_segment: String,
    network: matching::Network,
}

/// One solved point of a sweep.
#[derive(Serialize)]
struct SweepEvent<'a> {
    job: u64,
    index: usize,
    x: f64,
    metrics: Option<Metrics>,
    error: Option<String>,
    frame: Option<&'a Frame>,
}

/// Optimization progress.
#[derive(Serialize)]
struct ProgressEvent<'a> {
    job: u64,
    progress: &'a nec_engine::OptimizeProgress,
}

// ---- the commands ----------------------------------------------------------------------

fn dispatch(cmd: &str, a: &str) -> Result<String, String> {
    match cmd {
        "analyze" => {
            let d: DeckArgs = parse(a)?;
            out(&engine::analyze(&d.text, &store(), &d.model.unwrap_or_default())?)
        }
        "solve" => {
            let s: SolveArgs = parse(a)?;
            out(&engine::solve_at(&s.text, s.mhz, s.z0, &store(), &s.model.unwrap_or_default())?)
        }
        "near_field" => {
            let n: NearArgs = parse(a)?;
            out(&engine::near_field(&n.text, n.mhz, &n.request, &store(), &n.model.unwrap_or_default())?)
        }
        "report" => {
            let r: AtArgs = parse(a)?;
            out(&engine::report(&r.text, r.mhz, &store(), &r.model.unwrap_or_default())?)
        }
        "set_variables" => {
            let v: VariablesArgs = parse(a)?;
            let pairs: Vec<(&str, f64)> = v.values.iter().map(|(n, x)| (n.as_str(), *x)).collect();
            out(&nec_cards::set_variables(&v.text, &pairs))
        }
        "geometry_cards" => {
            const GEOMETRY: [&str; 13] = [
                "GW", "GA", "GH", "GM", "GX", "GR", "GS", "GC", "SP", "SM", "SC", "GF", "GE",
            ];
            let t: TextArgs = parse(a)?;
            let end = nec_cards::edit::geometry_end(&t.text);
            let cards = nec_cards::edit::cards(&t.text, &GEOMETRY)
                .map_err(|e| e.to_string())?
                .into_iter()
                .filter(|c| end.is_none_or(|e| c.line <= e))
                .collect();
            out(&GeometryCards { cards, insert_at: end })
        }
        "all_cards" => {
            let t: TextArgs = parse(a)?;
            out(&nec_cards::edit::cards(&t.text, &[]).map_err(|e| e.to_string())?)
        }
        "replace_card" => {
            let c: CardArgs = parse(a)?;
            out(&nec_cards::edit::replace_card(&c.text, c.line, &c.mnemonic, &c.fields)
                .ok_or_else(|| format!("no line {}", c.line))?)
        }
        "insert_card" => {
            let c: CardArgs = parse(a)?;
            out(&nec_cards::edit::insert_card(&c.text, c.line, &c.mnemonic, &c.fields))
        }
        "delete_line" => {
            let l: LineArgs = parse(a)?;
            out(&nec_cards::edit::delete_line(&l.text, l.line).ok_or_else(|| format!("no line {}", l.line))?)
        }
        "design_matching" => out(&design_matching(parse(a)?)),
        "apply_matching" => {
            let m: ApplyArgs = parse(a)?;
            out(&matching::apply(&m.text, m.tag, m.segment, &m.network, m.mhz).map_err(|e| e.to_string())?)
        }
        "matching_networks" => {
            let t: TextArgs = parse(a)?;
            let found: Vec<MatchInDeck> = matching::find(&t.text)
                .into_iter()
                .map(|(dummy_tag, feed_tag, feed_segment, network)| MatchInDeck { dummy_tag, feed_tag, feed_segment, network })
                .collect();
            out(&found)
        }
        "remove_matching" => {
            let r: RemoveArgs = parse(a)?;
            out(&matching::remove(&r.text, r.dummy_tag).map_err(|e| e.to_string())?)
        }
        "open_project" => {
            let o: OpenArgs = parse(a)?;
            let path = Path::new(&o.name);
            if Project::is_project_path(path) {
                out(&Project::from_toml(&o.text).map_err(|e| format!("{}: {e}", o.name))?)
            } else {
                let stem = path.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
                out(&Project::from_deck(&o.text, &stem))
            }
        }
        "project_text" => {
            let s: SaveArgs = parse(a)?;
            let text = if Project::is_project_path(Path::new(&s.name)) {
                s.project.to_toml().map_err(|e| e.to_string())?
            } else {
                s.project.to_nec().to_string()
            };
            out(&text)
        }
        "sweep" => sweep_frequencies(parse(a)?),
        "parameter_sweep" => {
            let p: ParameterArgs = parse(a)?;
            let values = linspace(p.start, p.stop, p.steps.max(2));
            let cancel = AtomicBool::new(false);
            let job = p.job;
            sweep::parameter(&p.text, &p.name, &values, p.mhz, &p.options, &cancel, |i, r| {
                emit_point("param-point", job, i, values[i], r, None);
            });
            out(&job)
        }
        "optimize" => {
            let o: OptimizeArgs = parse(a)?;
            let cancel = AtomicBool::new(false);
            let job = o.job;
            // As the desktop app: every improvement, otherwise a heartbeat every 100 ms.
            let mut last: Option<(f64, Instant)> = None;
            let outcome = nec_engine::optimize(&o.text, &o.spec, &cancel, |p| {
                let due = last.is_none_or(|(cost, at)| p.cost < cost || at.elapsed() >= Duration::from_millis(100));
                if due {
                    last = Some((p.cost, Instant::now()));
                    emit("optimize-progress", &ProgressEvent { job, progress: p });
                }
            })
            .map_err(|e| e.to_string())?;
            out(&outcome)
        }
        "average_gain_test" => {
            let g: AverageGainArgs = parse(a)?;
            out(&checks::average_gain_test(&g.text, g.mhz, &store()).map_err(|e| e.to_string())?)
        }
        "convergence_test" => {
            let c: ConvergenceArgs = parse(a)?;
            let cancel = AtomicBool::new(false);
            let steps = checks::convergence_test(
                &c.text,
                c.mhz,
                c.steps,
                c.growth,
                nec_geom::MAX_SEGMENTS,
                &c.options,
                &cancel,
                |step| emit("convergence-step", step),
            )
            .map_err(|e| e.to_string())?;
            out(&steps)
        }
        other => Err(format!("unknown command `{other}`")),
    }
}

fn sweep_frequencies(s: SweepArgs) -> Result<String, String> {
    let freqs = linspace(s.start, s.stop, s.steps.max(2));
    // With auto-segmentation on, each frequency is solved on its own segmentation.
    let model = Model::with_options(&s.text, &nec_cards::SymbolTable::new(), &NgfStore::default(), &s.options.model)
        .map_err(|e| e.to_string())?;
    model.program().map_err(|e| e.to_string())?;
    let cancel = AtomicBool::new(false);
    let job = s.job;
    sweep::frequencies_with_frames(&model, &freqs, &s.options, &cancel, |i, r, frame| {
        emit_point("sweep-point", job, i, freqs[i], r, frame);
    });
    out(&job)
}

fn emit_point(event: &str, job: u64, index: usize, x: f64, r: &nec_engine::Result<Metrics>, frame: Option<&Frame>) {
    if matches!(r, Err(nec_engine::EngineError::Cancelled)) {
        return;
    }
    emit(event, &SweepEvent {
        job,
        index,
        x,
        metrics: r.as_ref().ok().copied(),
        error: r.as_ref().err().map(ToString::to_string),
        frame,
    });
}

fn design_matching(d: DesignArgs) -> Vec<MatchDesign> {
    use num_complex::Complex64 as C;
    let zl = C::new(d.z[0], d.z[1]);
    let (z0, mhz) = (d.z0, d.mhz);
    let nets = match d.request {
        MatchRequest::L { q_l, q_c } => matching::design_l(zl, z0, mhz, matching::Quality { q_l, q_c }),
        MatchRequest::Pi { q_net, q_l, q_c } => matching::design_pi(zl, z0, mhz, q_net, matching::Quality { q_l, q_c }),
        MatchRequest::Tee { q_net, q_l, q_c } => matching::design_tee(zl, z0, mhz, q_net, matching::Quality { q_l, q_c }),
        MatchRequest::Stub { line, stub_line, short, series } => matching::design_stub(zl, z0, mhz, line, stub_line, short, series),
        MatchRequest::Section { line, section } => matching::design_series_section(zl, z0, mhz, line, section),
    };
    nets.into_iter()
        .map(|network| {
            let zi = network.input_impedance(zl, mhz);
            MatchDesign { z_in: [zi.re, zi.im], swr: nec_engine::swr(zi, z0), loss: network.loss_fraction(zl, mhz), network }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    const DIPOLE: &str = "CE\nGW 1 9 0 -.2418 0 0 .2418 0 .0001\nGE 0\nEX 0 1 5 0 1 0\nFR 0 1 0 0 300 0\nEN\n";

    fn json(cmd: &str, args: serde_json::Value) -> serde_json::Value {
        serde_json::from_str(&call(cmd, &args.to_string(), None).expect(cmd)).expect("json")
    }

    #[test]
    fn solve_takes_the_desktop_arguments() {
        let s = json("solve", serde_json::json!({ "text": DIPOLE, "mhz": null, "z0": 50.0, "path": null, "model": null }));
        assert!((s["inputs"][0]["z"][0].as_f64().unwrap() - 72.08).abs() < 0.01);
    }

    #[test]
    fn remove_matching_reads_the_camel_case_key() {
        // The frontend sends `dummyTag`; a missing key would be a parse error, not "no network".
        let err = call("remove_matching", &serde_json::json!({ "text": DIPOLE, "dummyTag": 99 }).to_string(), None);
        assert!(err.as_ref().err().is_none_or(|e| !e.starts_with("bad arguments")), "{err:?}");
    }

    #[test]
    fn a_deck_round_trips_through_a_project() {
        let p = json("open_project", serde_json::json!({ "name": "dipole.nec", "text": DIPOLE }));
        let toml = json("project_text", serde_json::json!({ "name": "dipole.toml", "project": p }));
        let back = json("open_project", serde_json::json!({ "name": "dipole.toml", "text": toml }));
        assert_eq!(p, back);
    }

    #[test]
    fn unknown_commands_are_errors() {
        assert!(call("startup_file", "{}", None).is_err());
    }
}
